export type AnnotationType = "text" | "heading" | "table" | "image" | "list" | "formula" | "code" | "warning" | "caption" | "page_number";
export type NormalizedBox = [number, number, number, number];
export type ManualAnnotation = {
  id: string;
  page: number;
  bbox: NormalizedBox;
  type: AnnotationType;
  excluded: boolean;
  readingOrder?: number;
  sourceBlockIds?: string[];
  logicalGroupId?: string;
  logicalGroupNumber?: number;
  logicalGroupColor?: string;
  groupMemberIndex?: number;
  groupMemberCount?: number;
  groupPages?: number[];
  regionMemberIds?: string[];
  manual?: boolean;
  mergedFromIds?: string[];
  members?: ManualAnnotation[];
  groupMembers?: ManualAnnotation[];
  originalType?: AnnotationType;
  revisionOf?: string;
  text?: string;
  manualText?: string;
  transcriptionSource?: "human";
  exclusionSuggested?: boolean;
  exclusionSuggestion?: string;
  exclusionReason?: string;
};
export type MineruDetection = ManualAnnotation & { layer?: "detection" };
export type AnnotationPolicyInput = MineruDetection & { text?: string; exclusionSuggested?: boolean; exclusionSuggestion?: string };
export type AnnotationSnapshot = { annotations: ManualAnnotation[]; suppressedSourceBlockIds: string[]; detectionExclusionOverrides?: Record<string, boolean> };
export type AnnotationState = { annotations: ManualAnnotation[]; mineruDetections: MineruDetection[]; detectionExclusionOverrides?: Record<string, boolean>; suppressedSourceBlockIds: string[]; undo: AnnotationSnapshot[]; redo: AnnotationSnapshot[] };
export type AnnotationSelection = { selectedIds: string[]; lastSelectedId: string | null; lockedBlockId: string | null };
export const ANNOTATION_TYPES: readonly AnnotationType[];
export const ANNOTATION_LABELS: Readonly<Record<AnnotationType, string>>;
export const ANNOTATION_SHORT_LABELS: Readonly<Record<AnnotationType, string>>;
export const ANNOTATION_ICONS: Readonly<Record<AnnotationType, string>>;
export function annotationLabelForSize(type: AnnotationType, width: number, height: number): { mode: "full" | "short" | "icon"; label: string; fullLabel: string; shortLabel: string; icon: string; tooltip: string };
export function createAnnotationState(annotations?: ManualAnnotation[], mineruDetections?: MineruDetection[]): AnnotationState;
export function applyAnnotationExclusionPolicy(detections: AnnotationPolicyInput[]): AnnotationPolicyInput[];
export function effectiveAnnotations(state: AnnotationState): Array<ManualAnnotation & { layer: "manual" | "detection" }>;
export function updateAnnotationSelection(current: AnnotationSelection, blockId: string, options?: { toggle?: boolean; rangeIds?: string[] }): AnnotationSelection;
export function normalizeBox(start: { x: number; y: number }, end: { x: number; y: number }, width: number, height: number): NormalizedBox;
export function denormalizeBox(bbox: NormalizedBox, width: number, height: number): NormalizedBox;
export function annotationIdsInBox(annotations: Array<{ id: string; page: number; bbox: readonly number[] }>, bbox: NormalizedBox, options?: { pages?: number[]; fullyContained?: boolean; containmentTolerance?: number }): string[];
export function addAnnotation(state: AnnotationState, input: { id: string; page: number; bbox: NormalizedBox; readingOrder?: number }): AnnotationState;
export function changeAnnotationType(state: AnnotationState, ids: string[], type: AnnotationType): AnnotationState;
export function reviseDetectionType(state: AnnotationState, ids: string[], type: Exclude<AnnotationType, "page_number">): AnnotationState;
export function toggleAnnotationExclusion(state: AnnotationState, ids: string[]): AnnotationState;
export function deleteAnnotations(state: AnnotationState, ids: string[]): AnnotationState;
export function mergeAnnotations(state: AnnotationState, ids: string[], options?: { crossPage?: boolean; groupId?: string }): AnnotationState;
export function splitAnnotations(state: AnnotationState, ids: string[]): AnnotationState;
export function undoAnnotationChange(state: AnnotationState): AnnotationState;
export function redoAnnotationChange(state: AnnotationState): AnnotationState;
